<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Core\TenantFeatures;
use EventMenu\Services\TicketService;

$pdo=Database::connection();$slug=trim((string)($_GET['evento']??''));$error=null;
$s=$pdo->prepare('SELECT e.*,t.name tenant_name FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.slug=? AND e.status="published" AND t.status="active" LIMIT 1');$s->execute([$slug]);$event=$s->fetch();
if(!$event||!TenantFeatures::events((int)($event['tenant_id']??0))){http_response_code(404);exit('Evento não encontrado.');}

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sua sessão expirou. Atualize a página.';
    else{
        try{
            $reservation=(new TicketService())->reservePublic((int)$event['id'],(int)($_POST['batch_id']??0),(int)($_POST['quantity']??1),[
                'name'=>(string)($_POST['name']??''),'email'=>(string)($_POST['email']??''),'phone'=>(string)($_POST['phone']??'')
            ],trim((string)($_POST['coupon']??''))?:null,trim((string)($_POST['promoter']??''))?:null);
            header('Location: '.app_url('pedido.php?t='.rawurlencode($reservation['public_token'])),true,303);exit;
        }catch(Throwable$e){$error=$e->getMessage();}
    }
}

$b=$pdo->prepare('SELECT b.*,tt.name ticket_type_name,tt.description ticket_type_description,tt.access_area,tt.capacity_total ticket_type_capacity,tt.active ticket_type_active FROM ticket_batches b LEFT JOIN ticket_types tt ON tt.id=b.ticket_type_id WHERE b.event_id=? AND b.active=1 ORDER BY COALESCE(tt.sort_order,9999),tt.name,b.id');$b->execute([$event['id']]);$batches=$b->fetchAll();
$count=$pdo->prepare('SELECT COUNT(*) FROM tickets WHERE tenant_id=? AND event_id=? AND status IN ("reserved","paid","checked_in")');$count->execute([$event['tenant_id'],$event['id']]);$usedCapacity=(int)$count->fetchColumn();
$eventCapacity=$event['capacity_total']!==null?(int)$event['capacity_total']:null;$eventRemaining=$eventCapacity!==null?max(0,$eventCapacity-$usedCapacity):null;
$typeUsage=[];$tu=$pdo->prepare('SELECT b.ticket_type_id,COUNT(*) used FROM tickets t JOIN ticket_batches b ON b.id=t.batch_id WHERE t.tenant_id=? AND t.event_id=? AND b.ticket_type_id IS NOT NULL AND t.status IN ("reserved","paid","checked_in") GROUP BY b.ticket_type_id');$tu->execute([$event['tenant_id'],$event['id']]);foreach($tu->fetchAll() as$r)$typeUsage[(int)$r['ticket_type_id']]=(int)$r['used'];

function ev_money(int$c):string{return 'R$ '.number_format($c/100,2,',','.');}
function ev_color(mixed$value,string$fallback):string{$v=strtolower(trim((string)$value));return preg_match('/^#[0-9a-f]{6}$/',$v)?$v:$fallback;}
$primary=ev_color($event['primary_color']??'','#6236df');$secondary=ev_color($event['secondary_color']??'','#20134f');$subtitle=trim((string)($event['public_subtitle']??''));$salesEnabled=(int)($event['sales_enabled']??1)===1;
$mapUrl=trim((string)($event['map_url']??''));$lat=$event['latitude']!==null?(float)$event['latitude']:null;$lng=$event['longitude']!==null?(float)$event['longitude']:null;$canonical=app_url('evento.php?evento='.rawurlencode($slug));
$starts=strtotime((string)$event['starts_at']);$ends=!empty($event['ends_at'])?strtotime((string)$event['ends_at']):null;
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title><?= Security::e($event['name']) ?> — EventMenu</title><meta name="description" content="<?= Security::e($subtitle!==''?$subtitle:mb_substr(strip_tags((string)$event['description']),0,180)) ?>"><link rel="canonical" href="<?= Security::e($canonical) ?>">
<style>
:root{--primary:<?= Security::e($primary) ?>;--secondary:<?= Security::e($secondary) ?>;--bg:#f7f7fb;--surface:#fff;--text:#252137;--muted:#77748a;--line:#e6e3ee;--soft:#f1edff;--success:#2ea969;--warning:#dd9224;--shadow:0 10px 30px rgba(49,40,84,.08)}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,select{font:inherit}.shell{width:min(1160px,100%);margin:auto;padding:16px 18px 64px}.top{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:7px 0 16px}.brand{font-size:18px;font-weight:900;color:var(--secondary)}.brand span{color:var(--primary)}.organizer{font-size:10px;color:var(--muted)}.hero{position:relative;overflow:hidden;min-height:390px;border-radius:19px;border:1px solid var(--line);background:linear-gradient(125deg,var(--secondary),color-mix(in srgb,var(--primary) 65%,var(--secondary)));display:flex;align-items:end;box-shadow:var(--shadow)}.hero.with-banner{background-size:cover;background-position:center}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(19,12,48,.06) 8%,rgba(19,12,48,.2) 42%,rgba(19,12,48,.88) 100%)}.hero-body{position:relative;z-index:1;color:#fff;padding:clamp(24px,5vw,48px);max-width:850px}.eyebrow{font-size:9px;font-weight:900;letter-spacing:.15em;color:#d8cfff}.hero h1{font-size:clamp(38px,7vw,72px);line-height:.94;letter-spacing:-2px;margin:8px 0 12px}.subtitle{font-size:clamp(16px,2vw,21px);line-height:1.35;margin:0 0 13px}.description{max-width:720px;color:#e7e2f4;font-size:12px;line-height:1.6}.hero-meta{display:flex;flex-wrap:wrap;gap:7px;margin-top:17px}.hero-pill{background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.2);border-radius:999px;padding:8px 11px;font-size:10px;font-weight:750;backdrop-filter:blur(8px)}.event-nav{display:flex;align-items:center;justify-content:space-between;gap:12px;background:#fff;border:1px solid var(--line);border-radius:13px;padding:10px 12px;margin:12px 0 14px;box-shadow:0 5px 16px rgba(49,40,84,.04)}.event-nav-links{display:flex;gap:7px;overflow:auto}.event-nav a{white-space:nowrap;font-size:10px;font-weight:800;padding:7px 10px;border-radius:8px;color:#605b70}.event-nav a:hover{background:var(--soft);color:var(--primary)}.event-cta{background:var(--primary)!important;color:#fff!important}.alert{padding:12px 14px;border-radius:10px;background:#fff0f1;color:#a3404a;border:1px solid #efc8cc;margin-bottom:12px;font-size:11px}.layout{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(270px,.65fr);gap:15px;align-items:start}.section,.side-card{background:#fff;border:1px solid var(--line);border-radius:15px;padding:18px;box-shadow:var(--shadow)}.section-head{display:flex;align-items:end;justify-content:space-between;gap:10px;margin-bottom:13px}.section-head h2,.side-card h2{margin:3px 0 0;font-size:20px}.section-head .muted{font-size:9px}.section .eyebrow,.side-card .eyebrow{color:var(--primary)}.muted{color:var(--muted)}.ticket-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ticket{border:1px solid var(--line);border-radius:13px;padding:14px;background:#fff;box-shadow:0 4px 14px rgba(49,40,84,.035)}.ticket-top{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.ticket h3{margin:4px 0;font-size:16px}.price{font-size:17px;font-weight:900;color:var(--primary);white-space:nowrap}.availability{font-size:9px;color:var(--muted)}.type-description{font-size:10px;line-height:1.45;color:var(--muted);min-height:29px}.buy{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:11px}.buy label{display:grid;gap:4px;color:#686376;font-size:9px;font-weight:750}.buy input,.buy select{width:100%;border:1px solid var(--line);background:#fff;color:var(--text);border-radius:8px;padding:8px;outline:0}.buy input:focus,.buy select:focus{border-color:#9d84eb;box-shadow:0 0 0 2px rgba(98,54,223,.08)}.buy button{grid-column:1/-1;border:0;background:var(--primary);color:#fff;border-radius:9px;padding:10px;font-size:10px;font-weight:900;cursor:pointer}.closed{margin-top:10px;padding:10px;border-radius:9px;background:#f6f4f9;color:#777286;font-size:10px}.side-stack{display:grid;gap:12px}.capacity{font-size:34px;font-weight:950;color:var(--primary);display:block;margin:4px 0}.side-card p{font-size:10px;line-height:1.55}.map-box{overflow:hidden;border:1px solid var(--line);border-radius:11px;margin-top:10px;background:#f2f1f5}.map-box iframe{border:0;width:100%;height:220px;display:block}.map-link{display:block;padding:10px 12px;font-size:10px;font-weight:850;color:var(--primary)}.benefits{display:flex;flex-wrap:wrap;gap:6px;margin-top:10px}.benefit{padding:7px 9px;border-radius:999px;background:var(--soft);color:#5b4b89;font-size:9px;font-weight:750}.powered{text-align:center;color:#928da0;font-size:10px;padding-top:28px}
@media(max-width:880px){.shell{padding:10px 10px 54px}.hero{min-height:340px;border-radius:15px}.layout{grid-template-columns:1fr}.ticket-grid{grid-template-columns:1fr}.side-stack{grid-template-columns:repeat(2,minmax(0,1fr))}.event-nav{overflow:auto}}
@media(max-width:560px){.hero{min-height:310px}.hero-body{padding:22px}.hero h1{letter-spacing:-1px}.event-nav{display:block}.event-nav-links{padding-bottom:5px}.event-cta{display:block;text-align:center}.side-stack{grid-template-columns:1fr}.buy{grid-template-columns:1fr}.buy button{grid-column:auto}.top .organizer{display:none}}
</style></head><body><main class="shell">
<header class="top"><div class="brand">EventMenu <span>Premium</span></div><div class="organizer">Organização · <?= Security::e($event['tenant_name']) ?></div></header>
<section class="hero<?= $event['banner_url']?' with-banner':'' ?>"<?php if($event['banner_url']):?> style="background-image:linear-gradient(180deg,rgba(20,12,51,.05),rgba(20,12,51,.58)),url('<?= Security::e($event['banner_url']) ?>')"<?php endif;?>><div class="hero-body"><span class="eyebrow"><?= Security::e(mb_strtoupper((string)($event['event_type']??'EVENTO'))) ?></span><h1><?= Security::e($event['name']) ?></h1><?php if($subtitle!==''):?><p class="subtitle"><?= Security::e($subtitle) ?></p><?php endif;?><div class="description"><?= nl2br(Security::e($event['description']??'')) ?></div><div class="hero-meta"><span class="hero-pill"><?= Security::e(date('d/m/Y',$starts)) ?></span><span class="hero-pill">A partir de <?= Security::e(date('H:i',$starts)) ?></span><?php if($event['venue']):?><span class="hero-pill"><?= Security::e($event['venue']) ?></span><?php endif;?><?php if($eventCapacity!==null):?><span class="hero-pill">Capacidade <?= $eventCapacity ?></span><?php endif;?></div></div></section>
<nav class="event-nav"><div class="event-nav-links"><a href="#ingressos">Ingressos</a><a href="#local">Local</a><?php if($eventCapacity!==null):?><a href="#capacidade">Capacidade</a><?php endif;?></div><a class="event-cta" href="#ingressos">Comprar ingresso →</a></nav>
<?php if($error):?><div class="alert"><?= Security::e($error) ?></div><?php endif;?>
<div class="layout"><section class="section" id="ingressos"><div class="section-head"><div><span class="eyebrow">INGRESSOS</span><h2>Escolha seu ingresso</h2></div><span class="muted">QR individual após confirmação</span></div><?php if(!$salesEnabled):?><div class="closed"><strong>Venda online temporariamente indisponível.</strong><br>A organização desativou novas compras.</div><?php elseif(!$batches):?><div class="closed">Nenhum lote disponível no momento.</div><?php else:?><div class="ticket-grid"><?php foreach($batches as$batch):
$available=max(0,(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved']);
if($eventRemaining!==null)$available=min($available,$eventRemaining);
if(!empty($batch['ticket_type_id'])&&!empty($batch['ticket_type_capacity'])){$typeRemaining=max(0,(int)$batch['ticket_type_capacity']-($typeUsage[(int)$batch['ticket_type_id']]??0));$available=min($available,$typeRemaining);}
$now=time();$open=(!$batch['sales_start']||strtotime($batch['sales_start'])<=$now)&&(!$batch['sales_end']||strtotime($batch['sales_end'])>=$now);$free=(int)$batch['price_cents']===0;$typeActive=empty($batch['ticket_type_id'])||(int)$batch['ticket_type_active']===1;
?><article class="ticket"><div class="ticket-top"><div><span class="eyebrow"><?= Security::e($batch['ticket_type_name']?:'INGRESSO') ?></span><h3><?= Security::e($batch['name']) ?></h3><?php if($batch['access_area']):?><div class="availability">Acesso: <?= Security::e($batch['access_area']) ?></div><?php endif;?></div><div class="price"><?= $free?'Grátis':ev_money((int)$batch['price_cents']) ?></div></div><?php if($batch['ticket_type_description']):?><p class="type-description"><?= Security::e($batch['ticket_type_description']) ?></p><?php endif;?><div class="availability"><?= $available ?> disponível(is) agora</div><?php if($available>0&&$open&&$typeActive):?><form method="post" class="buy"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="batch_id" value="<?= (int)$batch['id'] ?>"><label>Quantidade<select name="quantity"><?php for($i=1;$i<=min(10,$available);$i++):?><option value="<?= $i ?>"><?= $i ?></option><?php endfor;?></select></label><label>Nome<input name="name" required autocomplete="name"></label><label>E-mail<input type="email" name="email" autocomplete="email"></label><label>Telefone<input name="phone" autocomplete="tel"></label><label>Cupom<input name="coupon" autocomplete="off" placeholder="Opcional"></label><label>Promotor / afiliado<input name="promoter" autocomplete="off" placeholder="Opcional"></label><button><?= $free?'Emitir ingresso':'Reservar e pagar' ?></button></form><?php elseif(!$open):?><div class="closed">Fora do período de venda.</div><?php elseif($available<=0):?><div class="closed">Esgotado / capacidade atingida.</div><?php else:?><div class="closed">Tipo de ingresso indisponível.</div><?php endif;?></article><?php endforeach;?></div><?php endif;?></section>
<aside class="side-stack"><section class="side-card" id="local"><span class="eyebrow">LOCAL</span><h2><?= Security::e($event['venue']?:'Local do evento') ?></h2><?php if($event['address']):?><p class="muted"><?= Security::e($event['address']) ?></p><?php endif;?><?php if($lat!==null&&$lng!==null):$bbox=($lng-0.008).','.($lat-0.006).','.($lng+0.008).','.($lat+0.006);$osm='https://www.openstreetmap.org/export/embed.html?bbox='.rawurlencode($bbox).'&layer=mapnik&marker='.rawurlencode($lat.','.$lng);?><div class="map-box"><iframe title="Mapa do evento" loading="lazy" referrerpolicy="no-referrer" src="<?= Security::e($osm) ?>"></iframe><?php if($mapUrl!==''):?><a class="map-link" href="<?= Security::e($mapUrl) ?>" target="_blank" rel="noopener noreferrer">Abrir rota / mapa ↗</a><?php endif;?></div><?php elseif($mapUrl!==''):?><a class="map-link" href="<?= Security::e($mapUrl) ?>" target="_blank" rel="noopener noreferrer">Abrir localização no mapa ↗</a><?php endif;?></section>
<?php if($eventCapacity!==null):?><section class="side-card" id="capacidade"><span class="eyebrow">CAPACIDADE</span><strong class="capacity"><?= $eventRemaining ?></strong><p class="muted">vaga(s) ainda disponíveis considerando reservas e ingressos emitidos.</p></section><?php endif;?>
<section class="side-card"><span class="eyebrow">EXPERIÊNCIA</span><h2>Entrada segura por QR</h2><p class="muted">Cada ingresso possui QR Code individual e validação única no check-in.</p><div class="benefits"><span class="benefit">QR individual</span><span class="benefit">Check-in</span><span class="benefit">Pagamento online</span><?php if(!empty($event['bar_enabled'])):?><span class="benefit">Bar no evento</span><?php endif;?></div></section></aside></div>
<footer class="powered">EventMenu — tecnologia para gastronomia, eventos e boas experiências.</footer></main></body></html>
